"""End-to-end: ``runtime_estimation_autogenerated_report.md`` formatting.

Pins the layout of the per-spec runtime report:

- a `## Contents` heading followed by a bulleted list, one bullet per
  target opcode, in first-appearance order;
- every TOC link target resolves to a real `## <opcode>` heading
  (i.e. anchors preserve underscores, matching GFM);
- each `### <test_name>` heading (with optional ``— combo `<combo>``` suffix)
  is followed by the headline client table and then one `<details>` block
  per client, with summary ``<client> — NNLS regression summary``;
- when plots are enabled, the three plot embeds (regression, bootstrap,
  diagnostics) live *inside* the same per-client `<details>` block.
"""

from __future__ import annotations

import re
from pathlib import Path

from _data_synth import (
    ClientModel,
    base_config,
    cross_product_fixtures,
    make_block_limit_fixtures,
    run_pipeline,
    write_standard_inputs,
)


def _build_two_tests(tmp_path: Path, *, plots: bool):
    """Two test_names so the TOC bulleted list has more than one entry."""
    arith = make_block_limit_fixtures(
        test_file="test_arithmetic",
        test_name="test_arithmetic",
        target_opcode="ADD",
        params={"opcode": "ADD"},
        target_opcount_per_million=500_000,
    )
    storage = cross_product_fixtures(
        test_file="test_storage_set",
        test_name="test_storage_set",
        param_grid={"value_sent": ["1", "5"]},
        target_opcode_for="SSTORE",
        target_opcount_per_million=400_000,
    )
    models = {
        "geth": ClientModel(intercept=80.0, slope=2.0e-5),
        "besu": ClientModel(intercept=100.0, slope=3.0e-5),
    }
    config = base_config(
        plots=plots,
        models_custom=[
            {
                "test_name": "test_arithmetic",
                "target_operation": "ADD",
                "model_params": {"target_coef": "OPCODE_ADD"},
            },
            {
                "test_name": "test_storage_set",
                "target_operation": "SSTORE",
                "model_by": "value_sent",
                "model_params": {"target_coef": "COLD_STORAGE_WRITE"},
            },
        ],
    )
    return write_standard_inputs(
        tmp_path,
        fixtures=arith + storage,
        models=models,
        config=config,
        noise_pct=0.002,
        seed=13,
    )


def _read_report(out_dir: Path) -> str:
    return (out_dir / "runtime_estimation_autogenerated_report.md").read_text()


def test_contents_is_a_bulleted_toc(tmp_path: Path) -> None:
    config_yaml, runtimes_csv, opcounts_json, out_dir = _build_two_tests(
        tmp_path, plots=False
    )
    run_pipeline(config_yaml, runtimes_csv, opcounts_json, out_dir)

    report = _read_report(out_dir)
    assert "## Contents" in report, "missing '## Contents' TOC heading"
    # No leftover inline-list TOC.
    assert "**Contents:**" not in report

    # The bullets immediately under '## Contents' (before the next heading)
    # must be markdown list items, one per target opcode, in first-appearance
    # order across specs.
    contents_section = report.split("## Contents", 1)[1].split("\n## ", 1)[0]
    bullets = [line for line in contents_section.splitlines() if line.startswith("- [")]
    assert bullets == [
        "- [ADD](#add)",
        "- [SSTORE](#sstore)",
    ], f"unexpected TOC bullets: {bullets!r}"


def test_toc_anchors_point_at_real_headings(tmp_path: Path) -> None:
    """Every `(#anchor)` in the TOC must match a heading that GFM would
    actually render with that id — i.e. underscores in `test_*` survive."""
    config_yaml, runtimes_csv, opcounts_json, out_dir = _build_two_tests(
        tmp_path, plots=False
    )
    run_pipeline(config_yaml, runtimes_csv, opcounts_json, out_dir)

    report = _read_report(out_dir)
    h2_titles = re.findall(r"^## (.+)$", report, flags=re.MULTILINE)

    # GFM anchor: lowercase, drop punctuation outside [a-z0-9_-], space→'-'.
    def gfm_anchor(title: str) -> str:
        out: list[str] = []
        for ch in title.lower():
            if ch.isalnum() or ch in "_-":
                out.append(ch)
            elif ch == " ":
                out.append("-")
        return "".join(out)

    valid_anchors = {gfm_anchor(t) for t in h2_titles}
    contents_section = report.split("## Contents", 1)[1].split("\n## ", 1)[0]
    toc_anchors = re.findall(r"\(#([^)]+)\)", contents_section)
    assert toc_anchors, "TOC produced no anchors"
    for anchor in toc_anchors:
        assert anchor in valid_anchors, (
            f"TOC anchor #{anchor} does not match any rendered heading "
            f"(valid: {sorted(valid_anchors)})"
        )


def test_per_client_details_wrap_summary_and_plots(tmp_path: Path) -> None:
    """For each `### test_arithmetic` block under `## ADD`: each client
    appears once as `<details><summary>{client} — NNLS regression
    summary</summary>` (no per-client h4) and the three plot embeds for
    that client all sit inside that same `<details>...</details>` block."""
    config_yaml, runtimes_csv, opcounts_json, out_dir = _build_two_tests(
        tmp_path, plots=True
    )
    run_pipeline(config_yaml, runtimes_csv, opcounts_json, out_dir)

    report = _read_report(out_dir)
    # Old per-client h4 headings are gone.
    assert not re.search(r"^#### (besu|geth)\b", report, flags=re.MULTILINE), (
        "expected per-client `#### {client}` headings to be removed"
    )

    # Each <details> opens with the new summary format.
    summaries = re.findall(r"<details><summary>([^<]+)</summary>", report)
    assert summaries, "no <details> blocks found"
    for summary in summaries:
        assert summary.endswith(" — NNLS regression summary"), (
            f"unexpected summary text: {summary!r}"
        )
        client = summary.removesuffix(" — NNLS regression summary").strip()
        assert client in {"besu", "geth"}, f"unexpected client in summary: {client!r}"

    # The three runtime plot embeds for the ADD/test_arithmetic/besu fit must
    # fall inside a single <details>...</details> block whose summary names
    # besu, nested under the '## ADD' / '### test_arithmetic' subsection.
    add_besu_re = re.compile(
        r"<details><summary>besu — NNLS regression summary</summary>(.*?)</details>",
        re.DOTALL,
    )
    # ADD section: from '## ADD' to the next '## '.
    add_section = re.search(r"## ADD\b(.*?)(?=\n## |\Z)", report, flags=re.DOTALL)
    assert add_section, "missing '## ADD' section in report"
    # test_arithmetic subsection within ADD: from '### test_arithmetic' to the
    # next '### ' or end of the ADD section.
    arith_subsection = re.search(
        r"### test_arithmetic\b(.*?)(?=\n### |\Z)",
        add_section.group(1),
        flags=re.DOTALL,
    )
    assert arith_subsection, "missing '### test_arithmetic' subsection under '## ADD'"
    besu_block_match = add_besu_re.search(arith_subsection.group(1))
    assert besu_block_match, (
        "no besu <details> block under '## ADD' / '### test_arithmetic'"
    )
    besu_block = besu_block_match.group(1)
    for family in ("regression", "bootstrap", "diagnostics"):
        embed = f"![](figs/runtime/ADD__test_arithmetic__all__besu__{family}.png)"
        assert embed in besu_block, (
            f"expected {family} plot embed inside the besu <details> block; "
            f"block content was: {besu_block[:400]!r}"
        )


def test_details_blocks_are_balanced(tmp_path: Path) -> None:
    """Trivial sanity: opening and closing `<details>` tags balance."""
    config_yaml, runtimes_csv, opcounts_json, out_dir = _build_two_tests(
        tmp_path, plots=True
    )
    run_pipeline(config_yaml, runtimes_csv, opcounts_json, out_dir)

    report = _read_report(out_dir)
    opens = report.count("<details>")
    closes = report.count("</details>")
    assert opens == closes, f"unbalanced <details>: {opens} open vs {closes} close"
    assert opens > 0
